package com.bookstore.entity;
import jakarta.persistence.*; import jakarta.validation.constraints.*; import java.math.BigDecimal;
@Entity @Table(name="books")
public class Book { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotBlank @Size(max=180) @Column(nullable=false) private String title; @NotBlank @Size(max=20) @Column(nullable=false,unique=true) private String isbn; @NotNull @DecimalMin("0.0") @Column(nullable=false,precision=10,scale=2) private BigDecimal price; @NotNull @Min(0) @Column(nullable=false) private Integer stockQuantity=0; @Size(max=500) private String imageUrl; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="author_id") private Author author; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="category_id") private Category category; public Book(){} public Long getId(){return id;} public void setId(Long v){id=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getIsbn(){return isbn;} public void setIsbn(String v){isbn=v;} public BigDecimal getPrice(){return price;} public void setPrice(BigDecimal v){price=v;} public Integer getStockQuantity(){return stockQuantity;} public void setStockQuantity(Integer v){stockQuantity=v;} public String getImageUrl(){return imageUrl;} public void setImageUrl(String v){imageUrl=v;} public Author getAuthor(){return author;} public void setAuthor(Author v){author=v;} public Category getCategory(){return category;} public void setCategory(Category v){category=v;} }
